//! Puente de las decisiones de construcción de la IA con el mundo vivo.
use p3_core::{ai::reputation::Merchant,buildings::Site,economy::{ai_build_interval,ai_build_position,ai_construction_demand::{self,BusinessRank,OfficeDemand,OfficeRank,OfficeSelect,Placement},trade::OfficeStock,world::EconomyWorld},pump::Operation,rng::CrtRand};

struct Map<'a>{towns:&'a [p3_core::town::Town],sites:&'a [Site],images:&'a [Vec<u8>],tick:u32,merchant_count:u16}
impl Placement for Map<'_>{
    fn near_office(&mut self,city:u8,office:usize,row:&mut u8,col:&mut u8,skip:u8,kind:u8)->Result<(),String>{let i=usize::from(city);let town=self.towns.get(i).ok_or("ciudad de IA ausente")?;let site=self.sites.get(i).ok_or("plano de IA ausente")?;let office=self.images.get(office).ok_or("oficina de IA ausente")?;if office.get(0x2c6)!=Some(&city){return Err("oficina de IA en ciudad distinta".into())}ai_build_position::near(town,site,office,row,col,i32::from(skip),kind,self.tick)}
    fn nearest(&mut self,city:u8,row:&mut u8,col:&mut u8,kind:u8,flag:bool)->Result<bool,String>{let i=usize::from(city);let town=self.towns.get(i).ok_or("ciudad de IA ausente")?;let site=self.sites.get(i).ok_or("plano de IA ausente")?;crate::lender::validate(town,site,self.merchant_count)?;std::panic::catch_unwind(std::panic::AssertUnwindSafe(||site.find_nearest_cell_for_type(town,row,col,i32::from(kind),0,flag,0xe0))).map_err(|_|"búsqueda de construcción IA fuera del plano".into())}
}
fn word(b:&[u8],at:usize)->u16{u16::from_le_bytes([b[at],b[at+1]])}

/// Prepara la operación y el estado CRT sin modificar el mundo ni la cola.
pub(crate) fn plan(world:&EconomyWorld,sites:&[Site],images:&[Vec<u8>],stocks:&[OfficeStock],businesses:&[[u8;20]],merchants:&[Merchant],tick:u32,rng:Option<CrtRand>)->Result<(Option<Operation>,Option<CrtRand>),String>{
    let count=usize::from(world.merchant_count);let merchants=merchants.get(..count).ok_or("comerciantes de IA ausentes")?;if ai_build_interval::decision_is_empty(merchants)?{return Ok((None,rng))}let mut random=rng.ok_or("estado CRT de construcción IA ausente")?;
    if sites.len()!=world.towns.len()||world.tick_entries.len()!=world.towns.len()||images.len()!=world.offices.len()||stocks.len()!=images.len()||images.iter().any(|v|v.len()!=0x44c)||businesses.len()!=world.merchant_facilities.len(){return Err("datos de construcción IA incompletos".into())}
    let mut demand=Vec::with_capacity(images.len());let mut rank_offices=Vec::with_capacity(images.len());let mut select_offices=Vec::with_capacity(images.len());for(i,image)in images.iter().enumerate(){let next=world.offices[i].next;let owner=stocks[i].owner;if owner!=u16::MAX&&word(image,0x2c4)!=owner{return Err("propietario de oficina de IA desincronizado".into())}demand.push(OfficeDemand{next,consumption:stocks[i].business_consumption});rank_offices.push(OfficeRank{next,owner,first_business:world.offices[i].first_facility});select_offices.push(OfficeSelect{next,owner,stock:stocks[i].stock,target:stocks[i].ai_target})}
    let rank_businesses=businesses.iter().zip(&world.merchant_facilities).map(|(b,f)|BusinessRank{next:f.next,employees:f.employees,maximum:word(b,12)}).collect::<Vec<_>>();let records=sites.iter().map(|site|{if site.records.len()%8!=0{return Err("registros de ciudad truncados".into())}Ok(site.records.chunks_exact(8).map(|r|r.try_into().expect("ocho bytes")).collect::<Vec<[u8;8]>>())}).collect::<Result<Vec<_>,String>>()?;let date=p3_core::calendar::Calendar::for_tick(tick);let scores=ai_construction_demand::calculate(&world.towns,&demand,&world.tick_entries,date.month)?;let ranking=ai_construction_demand::rank(&scores,&world.towns,&records,&rank_offices,&rank_businesses,merchants,&mut random)?;let mut map=Map{towns:&world.towns,sites,images,tick,merchant_count:world.merchant_count};let op=ai_construction_demand::select(&scores,&ranking,&world.towns,&select_offices,merchants,date.day,&mut random,&mut map)?;Ok((op,Some(random)))
}
